import{_ as t,c as l,a2 as o,o as _}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1211第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经.md","filePath":"meditation/巴利文大藏经/1211第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经.md"}'),i={name:"meditation/巴利文大藏经/1211第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经.md"};function a(e,p,r,u,s,q){return _(),l("div",null,p[0]||(p[0]=[o('<h1 id="第一千二百一十一章-过失经-精进经-悔恨经-不悔恨经-了知经-结缚经-黑法经-白法经-行为经-安居经-增支部2集1经到10经" tabindex="-1">第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经 <a class="header-anchor" href="#第一千二百一十一章-过失经-精进经-悔恨经-不悔恨经-了知经-结缚经-黑法经-白法经-行为经-安居经-增支部2集1经到10经" aria-label="Permalink to &quot;第一千二百一十一章 过失经，精进经，悔恨经，不悔恨经，了知经，结缚经，黑法经，白法经，行为经，安居经 增支部2集1经到10经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部2集1经到10经</p><p>礼敬世尊、阿罗汉、正等正觉者。</p><p>增支部</p><p>二集</p><p>第一个五十集</p><ol><li><p>惩罚品</p></li><li><p>过失经</p></li><li><p>如是我闻:一时,世尊住在舍卫城祇树给孤独园。那时,世尊呼唤比丘们说:&quot;比丘们。&quot;那些比丘回答说:&quot;尊者。&quot;世尊如此说道:</p></li></ol><p>&quot;比丘们,有两种过失。哪两种?现世的过失和来世的过失。比丘们,什么是现世的过失?在这里,比丘们,有人看到国王抓住盗贼、作恶者后,实施各种刑罚:用鞭子抽打,用藤条抽打,用短棍抽打,砍断手,砍断脚,砍断手脚,割耳,割鼻,割耳鼻,以锅煮,剃光头皮,以火烧口,以火炬燃烧手,剥皮成条,剥皮成衣,以羚羊刑,以钩刑,以铜钱刑,以碱液刑,以门闩转刑,以草垫刑,浇热油,令狗啃食,生刺刑,以剑斩首。</p><p>他想:&#39;由于这些恶行,国王抓住盗贼、作恶者后,实施各种刑罚:用鞭子抽打,用藤条抽打,用短棍抽打,砍断手,砍断脚,砍断手脚,割耳,割鼻,割耳鼻,以锅煮,剃光头皮,以火烧口,以火炬燃烧手,剥皮成条,剥皮成衣,以羚羊刑,以钩刑,以铜钱刑,以碱液刑,以门闩转刑,以草垫刑,浇热油,令狗啃食,生刺刑,以剑斩首。如果我做这样的恶业,国王抓住我后也会对我实施这样的各种刑罚:用鞭子抽打……乃至以剑斩首。&#39;他因为害怕现世的过失而不去抢劫他人的财物。比丘们,这就叫做现世的过失。</p><p>比丘们,什么是来世的过失?在这里,比丘们,有人这样思考:&#39;身恶行在来世会有痛苦的恶果报,语恶行在来世会有痛苦的恶果报,意恶行在来世会有痛苦的恶果报。如果我以身、语、意行恶,那么我在身坏命终后,岂不是会堕入恶趣、恶道、地狱吗?&#39;他因为害怕来世的过失而断除身恶行,修习身善行;断除语恶行,修习语善行;断除意恶行,修习意善行;保持自己清净。比丘们,这就叫做来世的过失。</p><p>比丘们,这就是两种过失。因此,比丘们,你们应当如此学习:&#39;我们将害怕现世的过失,害怕来世的过失,我们将成为害怕过失、见过失可畏之人。&#39;比丘们,你们应当如此学习。比丘们,对于害怕过失、见过失可畏之人,可以期待他将从一切过失中解脱出来。&quot;</p><p>第一经</p><ol start="2"><li><p>精进经</p></li><li><p>&quot;比丘们,这两种精进在世间难以成就。哪两种?在家居士为了供养僧众衣服、饮食、住处、医药等必需品而精进,出家修行者为了舍弃一切执着而精进。比丘们,这就是世间难以成就的两种精进。</p></li></ol><p>比丘们,在这两种精进中,为舍弃一切执着而精进是最上的。因此,比丘们,你们应当如此学习:&#39;我们将为舍弃一切执着而精进。&#39;比丘们,你们应当如此学习。&quot;</p><p>第二经</p><ol start="3"><li><p>悔恨经</p></li><li><p>&quot;比丘们,这两种法会带来悔恨。哪两种?在这里,比丘们,有人做了身恶行,没有做身善行;做了语恶行,没有做语善行;做了意恶行,没有做意善行。他因为&#39;我做了身恶行&#39;而悔恨,&#39;我没有做身善行&#39;而悔恨;因为&#39;我做了语恶行&#39;而悔恨,&#39;我没有做语善行&#39;而悔恨;因为&#39;我做了意恶行&#39;而悔恨,&#39;我没有做意善行&#39;而悔恨。比丘们,这就是两种会带来悔恨的法。&quot;</p></li></ol><p>第三经</p><ol start="4"><li><p>不悔恨经</p></li><li><p>&quot;比丘们,这两种法不会带来悔恨。哪两种?在这里,比丘们,有人做了身善行,没有做身恶行;做了语善行,没有做语恶行;做了意善行,没有做意恶行。他因为&#39;我做了身善行&#39;而不悔恨,&#39;我没有做身恶行&#39;而不悔恨;因为&#39;我做了语善行&#39;而不悔恨,&#39;我没有做语恶行&#39;而不悔恨;因为&#39;我做了意善行&#39;而不悔恨,&#39;我没有做意恶行&#39;而不悔恨。比丘们,这就是两种不会带来悔恨的法。&quot;</p></li></ol><p>第四经</p><ol start="5"><li><p>了知经</p></li><li><p>&quot;比丘们,我了知两种法:对善法不知足,精进不退缩。比丘们,我精进不退缩,想:&#39;即使我的皮、筋、骨都干枯了,身体的肉和血都消失了,只要凭借人的力量、人的精进、人的努力所能达到的,我都不会停止努力,直到达到为止。&#39;比丘们,我由于不放逸而证得菩提,由于不放逸而证得无上的解脱。比丘们,如果你们也能精进不退缩,想:&#39;即使我的皮、筋、骨都干枯了,身体的肉和血都消失了,只要凭借人的力量、人的精进、人的努力所能达到的,我都不会停止努力,直到达到为止。&#39;那么比丘们,不久你们也将在现世中亲自证知、实现并安住于善男子正确地从在家生活出家所追求的无上梵行的完成。因此,比丘们,你们应当如此学习:&#39;我们将精进不退缩。即使我们的皮、筋、骨都干枯了,身体的肉和血都消失了,只要凭借人的力量、人的精进、人的努力所能达到的,我们都不会停止努力,直到达到为止。&#39;比丘们,你们应当如此学习。&quot;</p></li></ol><p>第五经</p><ol start="6"><li><p>结缚经</p></li><li><p>&quot;比丘们,有两种法。哪两种?对会导致结缚的法生起喜爱,对会导致结缚的法生起厌离。比丘们,对会导致结缚的法生起喜爱的人不能断除贪欲、嗔恨、愚痴。因为没有断除贪欲、嗔恨、愚痴,他就不能从生、老、死、忧、悲、苦、恼、绝望中解脱出来。我说他不能从苦中解脱出来。</p></li></ol><p>比丘们,对会导致结缚的法生起厌离的人能断除贪欲、嗔恨、愚痴。因为断除了贪欲、嗔恨、愚痴,他就能从生、老、死、忧、悲、苦、恼、绝望中解脱出来。我说他能从苦中解脱出来。比丘们,这就是两种法。&quot;</p><p>第六经</p><ol start="7"><li><p>黑法经</p></li><li><p>&quot;比丘们,这两种法是黑暗的。哪两种?无惭和无愧。比丘们,这就是两种黑暗的法。&quot;</p></li></ol><p>第七经</p><ol start="8"><li><p>白法经</p></li><li><p>&quot;比丘们,这两种法是光明的。哪两种?惭和愧。比丘们,这就是两种光明的法。&quot;</p></li></ol><p>第八经</p><ol start="9"><li><p>行为经</p></li><li><p>&quot;比丘们,这两种光明的法保护世间。哪两种?惭和愧。比丘们,如果这两种光明的法不保护世间,那么在这个世界上就不会有母亲、姨母、叔伯的妻子、老师的妻子或尊者的妻子等称呼。世界将会混乱,就像山羊、绵羊、鸡、猪、狗和豺狼一样。比丘们,正是因为这两种光明的法保护世间,所以才有母亲、姨母、叔伯的妻子、老师的妻子或尊者的妻子等称呼。&quot;</p></li></ol><p>第九经</p><ol start="10"><li><p>安居经</p></li><li><p>&quot;比丘们,有两种安居。哪两种?前安居和后安居。比丘们,这就是两种安居。&quot;</p></li></ol><p>第十经</p><p>惩罚品第一完结。</p><p>其摘要如下:</p><p>过失、精进,两个关于悔恨的,</p><p>了知为第五,</p><p>结缚、黑、白,</p><p>行为,以安居结束此品。</p>',39)]))}const c=t(i,[["render",a]]);export{d as __pageData,c as default};
